def massa_totale(distinta):
    tot = 0.0
    for voce in distinta.values():
        unit = voce.get("massa", 0.0) + massa_totale(voce.get("sotto", {}))
        tot += voce["qta"] * unit
    return tot


def conta_pezzi(distinta, molt=1, acc=None):
    acc = {} if acc is None else acc
    for nome, voce in distinta.items():
        n = molt * voce["qta"]
        acc[nome] = acc.get(nome, 0) + n
        conta_pezzi(voce.get("sotto", {}), n, acc)
    return acc

