from pytest import approx
from distinta import conta_pezzi, massa_totale

RUOTA = {
    "cerchio": {"massa": 2.0, "qta": 1},
    "bullone": {"massa": 0.05, "qta": 5},
}
CARRELLO = {
    "telaio": {"massa": 12.0, "qta": 1},
    "ruota": {"massa": 0.0, "qta": 4, "sotto": RUOTA},
    "bullone": {"massa": 0.05, "qta": 8},
}


def test_massa():
    assert massa_totale(CARRELLO) == approx(12 + 4 * (2 + 5 * 0.05) + 8 * 0.05)


def test_pezzi():
    p = conta_pezzi(CARRELLO)
    assert p["bullone"] == 4 * 5 + 8
    assert p["cerchio"] == 4
